// ── Core Bitwise Operations & Masks ───────────────────────────
const a = 0b1010; // 10
const b = 0b1100; // 12

console.log((a & b).toString(2));  // '1000' = 8
console.log((a | b).toString(2));  // '1110' = 14
console.log((a ^ b).toString(2));  // '0110' = 6
console.log((~a & 0xF).toString(2)); // '0101' = 5 (NOT, masked to 4 bits)

// ── Bit tricks ────────────────────────────────────────────────

// Check if bit k is set
const isBitSet = (n, k) => (n & (1 << k)) !== 0;
console.log(isBitSet(0b1010, 3)); // true  (bit 3 = 8 is set)
console.log(isBitSet(0b1010, 2)); // false (bit 2 = 4 is not set)

// Set bit k
const setBit = (n, k) => n | (1 << k);
console.log(setBit(0b1010, 2).toString(2)); // '1110'

// Clear bit k
const clearBit = (n, k) => n & ~(1 << k);
console.log(clearBit(0b1010, 3).toString(2)); // '0010'

// Toggle bit k
const toggleBit = (n, k) => n ^ (1 << k);
console.log(toggleBit(0b1010, 0).toString(2)); // '1011'

// Power of 2 check
const isPow2 = n => n > 0 && (n & (n - 1)) === 0;
console.log(isPow2(16)); // true   16 = 0b10000, 15 = 0b01111, AND = 0
console.log(isPow2(12)); // false  12 = 0b1100,  11 = 0b1011, AND ≠ 0

// XOR swap (no temp variable)
let x = 5, y = 9;
x ^= y; y ^= x; x ^= y;
console.log(x, y); // 9, 5

// ── Count Set Bits (Popcount) — Brian Kernighan ────────────────
function countBits(n) {
  let count = 0;
  while (n > 0) {
    n &= (n - 1); // clear the lowest set bit
    count++;
  }
  return count;
}
console.log(countBits(0b101101)); // 4

// ── XOR trick: find unique element ────────────────────────────
// Every element appears twice except one. XOR all → duplicates cancel.
function findUnique(arr) {
  return arr.reduce((acc, x) => acc ^ x, 0);
}
console.log(findUnique([2, 3, 4, 3, 2])); // 4
// 2^3^4^3^2 = (2^2)^(3^3)^4 = 0^0^4 = 4

// ── Enumerate all subsets of a bitmask ────────────────────────
// E.g. set = {0,2,3} encoded as 0b1101 = 13
function allSubsets(mask) {
  const subsets = [];
  for (let sub = mask; sub > 0; sub = (sub - 1) & mask) {
    subsets.push(sub);
  }
  subsets.push(0); // include empty subset
  return subsets;
}
console.log(allSubsets(0b101).map(s => s.toString(2)));
// ['101','100','001','0'] → subsets of {0,2}: {0,2},{2},{0},{}

// ── Extract all bit positions set in n ────────────────────────
function setBits(n) {
  const positions = [];
  let pos = 0;
  while (n > 0) {
    if (n & 1) positions.push(pos);
    n >>= 1;
    pos++;
  }
  return positions;
}
console.log(setBits(0b10110)); // [1, 2, 4] — bits 1,2,4 are set
